create function public.notify_route_event() returns trigger language plpgsql security definer set search_path='' as $$ declare b uuid; key text:=gen_random_uuid()::text; begin if old.name is not distinct from new.name and old.code is not distinct from new.code and old.status is not distinct from new.status then return new; end if; for b in select id from public.transport_buses where route_id=new.id loop perform public.emit_bus_notice(b,key,'Route updated','Your assigned route details changed. Check with the transport office.','transport'); end loop; return new; end $$;
create trigger notification_route after update of name,code,status on public.transport_routes for each row execute function public.notify_route_event();
revoke all on function public.notify_route_event() from public,anon,authenticated;
create or replace function public.notify_schedule_event() returns trigger language plpgsql security definer set search_path='' as $$ declare b uuid; key text:=gen_random_uuid()::text; begin for b in select id from public.transport_buses where route_id=case when tg_op='DELETE' then old.route_id else new.route_id end or (tg_op='UPDATE' and route_id=old.route_id) loop perform public.emit_bus_notice(b,key,'Schedule changed','A schedule for your assigned route was updated. Contact the transport office for details.','schedule'); end loop; if tg_op='DELETE' then return old; end if; return new; end $$;
create or replace function public.notify_assignment_event() returns trigger language plpgsql security definer set search_path='' as $$ declare u uuid; sid uuid; key text:=gen_random_uuid()::text; begin if tg_op='DELETE' then sid:=old.student_id; else sid:=new.student_id; end if; if tg_op='UPDATE' and old.bus_id is not distinct from new.bus_id and old.pickup_stop_id is not distinct from new.pickup_stop_id and old.student_id is not distinct from new.student_id then return new; end if; for u in select id from public.profiles where role='student' and (student_id=sid or (tg_op='UPDATE' and student_id=old.student_id)) loop perform public.emit_notice(u,key,'transport','Transport assignment changed','Your bus or pickup assignment was updated. Check your portal.','assignment'); end loop; perform public.emit_admin_notice(key,'Student assignment changed','A student transport assignment was updated.','assignment'); if tg_op='DELETE' then return old; end if; return new; end $$;
